c.cpp:
class Solution {
public:
    string truncateSentence(string s, int k) {
        stringstream ss(s);
        string word, res;
        while (k-- > 0 && ss >> word) {
            if (!res.empty()) res += ' ';
            res += word;
        }
        return res;
    }
};

c.java:
class Solution {
    public String truncateSentence(String s, int k) {
        String[] words = s.split(" ");
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < k; i++) {
            if (i > 0) sb.append(' ');
            sb.append(words[i]);
        }
        return sb.toString();
    }
}

